tool_input.command:
$out="$env:TEMP\dumpverify.yml"
$dl=Get-Content $out
$ft=1935  # 1-based line of preset-full-tools
Write-Host "=== preset-full-tools block (L$ft onwards, ~12 lines) ==="
for($i=$ft-1;$i -lt $ft+12;$i++){ Write-Host "$($i+1): $($dl[$i])" }
Write-Host "`n=== full-tools order + schedule/goal disabled state ==="
for($i=$ft-1;$i -lt [Math]::Min($ft+70,$dl.Count);$i++){
  $t=$dl[$i].Trim()
  if($t -match '^order:'){ Write-Host "order: $t" }
  if($t -eq '- id: tool-schedule' -or $t -eq '- id: tool-goal'){ Write-Host "$t -> next2=[$($dl[$i+2].Trim())]" }
  if($dl[$i].StartsWith('- id: ') -and $i -gt ($ft-1)){ Write-Host "(block ends before $($dl[$i]))"; break }
}
Write-Host "`n=== count plugins in full-tools ==="
$cnt=0
for($i=$ft-1;$i -lt [Math]::Min($ft+250,$dl.Count);$i++){
  if($dl[$i] -match '^\s{6}- id: '){ $cnt++ }
  if($i -gt $ft -and $dl[$i].StartsWith('- id: ')){ break }
}
Write-Host "plugin rows in full-tools: ~$cnt"

$env:DSH_HOME="C:\Users\Administrator\.dsh"
# Does dump show full-tools as a registered preset (roster)? The composed tree having preset-full-tools = it registers.
# Try the web API for preset list (localhost:3080). Common endpoint guess; else check registry exposure in dump.
# Check if the running web has an API listing presets:
$urls = @("http://127.0.0.1:3080/api/agent-preset","http://127.0.0.1:3080/api/presets","http://127.0.0.1:3080/agent-preset")
foreach($u in $urls){
  try{ $r=Invoke-WebRequest $u -TimeoutSec 3 -UseBasicParsing; Write-Host "$u -> $($r.StatusCode) $($r.Content.Substring(0,[Math]::Min(120,$r.Content.Length)))" }catch{ Write-Host "$u -> $($_.Exception.Message.Split([Environment]::NewLine)[0])" }
}
Write-Host "=== grep dump for 'roster' or registry listing of preset ids ==="
Get-Content "$env:TEMP\dumpverify.yml" | Select-String 'preset-(standard|full-tools|ptc|minimal|cordis)' | ForEach-Object {"L$($_.LineNumber): $($_.Line.Trim())"}

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
# newest sessions — find the full-tools one (preset should be full-tools, schedule/goal present)
Get-ChildItem $dir -Filter "session-*.json" | Sort-Object LastWriteTime -Descending | Select-Object -First 5 | ForEach-Object {
  try{
    $j=Get-Content $_.FullName -Raw|ConvertFrom-Json
    $hs=$j.record.rows.contextHeaders.val.headers
    if(-not $hs){ Write-Host "$($_.Name.Substring(8,8)) $($_.LastWriteTime.ToString('HH:mm:ss')) (no header) preset=$($j.record.rows.agentPreset.val)"; return }
    $names=@($hs[0].tools|ForEach-Object{$_.name})
    $bt=$j.record.rows.contextBreakdown.val.breakdown
    $sc=@($names|Where-Object{$_ -like 'schedule_*'}).Count
    $gl=@($names|Where-Object{$_ -in 'create_goal','update_goal','get_goal'}).Count
    "{0} {1:HH:mm:ss} preset={2} toolCount={3} toolsTok={4} schedule_*={5} goalTools={6} title={7}" -f $_.Name.Substring(8,8),$_.LastWriteTime,$j.record.rows.agentPreset.val,$names.Count,$bt.toolsTokens,$sc,$gl,$j.record.rows.title.val
  }catch{ Write-Host "err $_" }
}

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$ft = Get-ChildItem $dir -Filter "session-8ac072fd-*.json"|Select-Object -First 1
$ct=(Get-Content $ft.FullName -Raw|ConvertFrom-Json).record.rows.contextTimeline.val
Write-Host "=== commandStats ==="
$ct.commandStats | ConvertTo-Json -Depth 3 -Compress | ForEach-Object { if($_){$_.Substring(0,[Math]::Min(500,$_.Length))} }
Write-Host "=== commandCalls ==="
$ct.commandCalls | ConvertTo-Json -Depth 3 -Compress | ForEach-Object { if($_){$_.Substring(0,[Math]::Min(300,$_.Length))} }
Write-Host "=== any historical session that ran a 'goal' command? sample commandStats across recent sessions ==="
$found=$false
Get-ChildItem $dir -Filter "session-*.json" | Sort-Object LastWriteTime -Descending | Select-Object -First 40 | ForEach-Object {
  try{
    $j=Get-Content $_.FullName -Raw|ConvertFrom-Json
    $cs=$j.record.rows.contextTimeline.val.commandStats
    if($cs){ $s=$cs|ConvertTo-Json -Compress; if($s -match 'goal'){ Write-Host "$($_.Name.Substring(8,8)): $s"; $found=$true } }
  }catch{}
}
if(-not $found){ Write-Host "(no recent session shows a /goal command invocation in commandStats)" }

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
# newest sessions — find one with commandStats/commandCalls mentioning goal, or a goal was created
Get-ChildItem $dir -Filter "session-*.json" | Sort-Object LastWriteTime -Descending | Select-Object -First 6 | ForEach-Object {
  try{
    $j=Get-Content $_.FullName -Raw|ConvertFrom-Json
    $ct=$j.record.rows.contextTimeline.val
    $cs=$ct.commandStats; $cc=$ct.commandCalls
    $goalState = $j.record.rows.goal.val
    $hasGoal = $false
    if($goalState){ $gs=$goalState|ConvertTo-Json -Compress; if($gs -and $gs -ne 'null'){ $hasGoal=$true } }
    $cmdStr = if($cs){($cs|ConvertTo-Json -Compress)}else{''}
    $cmdHit = if($cmdStr -match 'goal'){'CMD-GOAL-HIT'}else{''}
    "{0} {1:HH:mm:ss} preset={2} goalField={3} cmdHit={4} cmdStats={5}" -f $_.Name.Substring(8,8),$_.LastWriteTime,$j.record.rows.agentPreset.val,$hasGoal,$cmdHit,($cmdStr.Substring(0,[Math]::Min(120,$cmdStr.Length)))
  }catch{}
}

