tool_input.command:
$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
# Check the goal.val content in the two new sessions (794ca361 greeting, 8ac072fd full-tools) — did /goal create/read a goal?
foreach($sid in '794ca361','8ac072fd'){
  $f=Get-ChildItem $dir -Filter "session-$sid-*.json"|Select-Object -First 1
  if(-not $f){continue}
  $j=Get-Content $f.FullName -Raw|ConvertFrom-Json
  Write-Host "=== $sid goal.val ==="
  $j.record.rows.goal.val | ConvertTo-Json -Depth 4 -Compress | ForEach-Object { if($_){$_.Substring(0,[Math]::Min(600,$_.Length))} }
}
Write-Host "`n=== search newest session raw logs for '/goal' or goal command handling ==="
$raws = Get-ChildItem "$env:USERPROFILE\.dsh\sessions" -Recurse -Filter "session.v4.jsonl.zstd" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 4
foreach($r in $raws){
  $sz=$r.Length
  Write-Host "$($r.Directory.Name) size=$sz mtime=$($r.LastWriteTime.ToString('HH:mm:ss'))"
}

$raws = Get-ChildItem "$env:USERPROFILE\.dsh\sessions" -Recurse -Filter "session.v4.jsonl.zstd" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 4
$code = @'
const fs=require('fs'),zlib=require('zlib');
function dec(buf){const M=Buffer.from([0x28,0xb5,0x2f,0xfd]);let idx=[];for(let i=0;(i=buf.indexOf(M,i))>=0;i+=4)idx.push(i);if(idx.length<=1)return zlib.zstdDecompressSync(buf).toString('utf8');let out='';for(let k=0;k<idx.length;k++){const s=idx[k],e=k+1<idx.length?idx[k+1]:buf.length;try{out+=zlib.zstdDecompressSync(buf.subarray(s,e)).toString('utf8')}catch{}}return out;}
const txt=dec(fs.readFileSync(process.argv[2]));
const lines=txt.split('\n').filter(Boolean);
let cmdGoal=0, goalMentions=0, samples=[];
for(const l of lines){const ll=l.toLowerCase();
  if(ll.includes('/goal')||ll.includes('"type":"command')||ll.includes('command/goal')||ll.includes('goal/command')){
    cmdGoal++; if(samples.length<4) samples.push(l.slice(0,220));
  }
  if(ll.includes('goal')) goalMentions++;
}
console.log('total lines:',lines.length,'slash/command-goal hits:',cmdGoal,'goal mentions:',goalMentions);
samples.forEach(s=>console.log('  S>',s));
'@
$tmp="$env:TEMP\decz.cjs"; Set-Content $tmp $code -Encoding UTF8
foreach($r in $raws){ Write-Host "==== $($r.Directory.Name) ===="; node $tmp $r.FullName 2>&1 | Select-Object -First 8 }
Remove-Item $tmp -ErrorAction SilentlyContinue

$raws = Get-ChildItem "$env:USERPROFILE\.dsh\sessions" -Recurse -Filter "session.v4.jsonl.zstd" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 5
$code = @'
const fs=require('fs'),zlib=require('zlib');
function dec(buf){const M=Buffer.from([0x28,0xb5,0x2f,0xfd]);let idx=[];for(let i=0;(i=buf.indexOf(M,i))>=0;i+=4)idx.push(i);if(idx.length<=1)return zlib.zstdDecompressSync(buf).toString('utf8');let out='';for(let k=0;k<idx.length;k++){const s=idx[k],e=k+1<idx.length?idx[k+1]:buf.length;try{out+=zlib.zstdDecompressSync(buf.subarray(s,e)).toString('utf8')}catch{}}return out;}
const txt=dec(fs.readFileSync(process.argv[2]));
const lines=txt.split('\n').filter(Boolean);
for(const l of lines){
  try{const o=JSON.parse(l); const t=o.type||'';
    // user message whose text starts with /goal, or command-type events
    if(t.includes('command') || t.includes('slash')){
      console.log('CMD-EVENT', t, l.slice(0,180));
    }
    if(t==='user/message'){
      const c=o.data&&o.data.content; const s=JSON.stringify(c||'');
      if(s.includes('/goal') && !s.includes('Team message')) console.log('USER-/goal', l.slice(0,200));
    }
  }catch{}
}
'@
$tmp="$env:TEMP\dz2.cjs"; Set-Content $tmp $code -Encoding UTF8
foreach($r in $raws){ $res = node $tmp $r.FullName 2>&1; if($res){ Write-Host "==== $($r.Directory.Name) mtime=$($r.LastWriteTime.ToString('HH:mm:ss')) ===="; $res | Select-Object -First 6 } }
Remove-Item $tmp -ErrorAction SilentlyContinue

$dl=Get-Content "$env:TEMP\d2.yml"
Write-Host "=== around L640-652 (top-level tool-workflow owner) ==="
$dl[639..651] | ForEach-Object {$_}
Write-Host "`n=== around L1870-1888 (optional-session-search group) ==="
$dl[1869..1887] | ForEach-Object {$_}
